     $nombre=trim((string)($_POST['nombre']??''));$propuesta=trim((string)($_POST['propuesta']??''));$seccion=(string)($_POST['seccion']??'');if($nombre==='')throw new RuntimeException('Ingresa el nombre del candidato.');if(!in_array($seccion,['matutina','vespertina'],true))throw new RuntimeException('Selecciona una sección válida.');
     if($accion==='crear'){$foto=isset($_FILES['foto'])?guardarFotoCandidato($_FILES['foto']):null;$stmt=$conexion->prepare('INSERT INTO eleccion_candidatos(eleccion_id,nombre,foto,propuesta,seccion,activo) VALUES(?,?,?,?,?,1)');$stmt->bind_param('issss',$eid,$nombre,$foto,$propuesta,$seccion);$stmt->execute();$cid=(int)$conexion->insert_id;$stmt->close();registrarAuditoria('CREATE','Votaciones','eleccion_candidato',$cid,'Candidato electoral registrado: '.$nombre.' ('.$seccion.').',null,null,['nombre'=>$nombre,'foto'=>$foto,'propuesta'=>$propuesta,'seccion'=>$seccion,'activo'=>1],'exito',null,null,'advertencia');flash('success','Candidato registrado correctamente.');}
     else{$cid=(int)($_POST['id']??0);$stmt=$conexion->prepare('SELECT * FROM eleccion_candidatos WHERE id=? AND eleccion_id=? LIMIT 1');$stmt->bind_param('ii',$cid,$eid);$stmt->execute();$antes=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$antes)throw new RuntimeException('Candidato no encontrado.');$fotoNueva=isset($_FILES['foto'])?guardarFotoCandidato($_FILES['foto']):null;$foto=$fotoNueva?:$antes['foto'];$stmt=$conexion->prepare('UPDATE eleccion_candidatos SET nombre=?,foto=?,propuesta=?,seccion=? WHERE id=? AND eleccion_id=?');$stmt->bind_param('ssssii',$nombre,$foto,$propuesta,$seccion,$cid,$eid);$stmt->execute();$stmt->close();if($fotoNueva&&!empty($antes['foto'])){$ruta=APP_ROOT.'/assets/uploads/votaciones/'.basename($antes['foto']);if(is_file($ruta))@unlink($ruta);}$despues=$antes;$despues['nombre']=$nombre;$despues['foto']=$foto;$despues['propuesta']=$propuesta;$despues['seccion']=$seccion;registrarAuditoria('UPDATE','Votaciones','eleccion_candidato',$cid,'Candidato electoral actualizado: '.$nombre.'.',null,$antes,$despues,'exito',null,null,'advertencia');flash('success','Candidato actualizado.');}
     redir('modulos/votaciones/candidatos.php');
