   if($accion==='eliminar'){$cid=(int)($_POST['id']??0);$stmt=$conexion->prepare('SELECT * FROM eleccion_candidatos WHERE id=? AND eleccion_id=? LIMIT 1');$stmt->bind_param('ii',$cid,$eid);$stmt->execute();$c=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$c)throw new RuntimeException('Candidato no encontrado.');$stmt=$conexion->prepare('SELECT COUNT(*) c FROM eleccion_votos WHERE candidato_id=?');$stmt->bind_param('i',$cid);$stmt->execute();$votos=(int)$stmt->get_result()->fetch_assoc()['c'];$stmt->close();if($votos>0)throw new RuntimeException('Este candidato ya tiene votos asociados y no puede eliminarse.');$stmt=$conexion->prepare('DELETE FROM eleccion_candidatos WHERE id=? AND eleccion_id=?');$stmt->bind_param('ii',$cid,$eid);$stmt->execute();$stmt->close();if(!empty($c['foto'])){$ruta=APP_ROOT.'/assets/uploads/votaciones/'.basename($c['foto']);if(is_file($ruta))@unlink($ruta);}registrarAuditoria('DELETE','Votaciones','eleccion_candidato',$cid,'Candidato electoral eliminado: '.$c['nombre'].'.',null,$c,null,'exito',null,null,'critica');flash('success','Candidato eliminado.');redir('modulos/votaciones/candidatos.php');}
 }catch(Throwable $ex){flash('error',$ex->getMessage());redir('modulos/votaciones/candidatos.php');}
}
$stmt=$conexion->prepare('SELECT c.*,(SELECT COUNT(*) FROM eleccion_votos v WHERE v.candidato_id=c.id) votos FROM eleccion_candidatos c WHERE c.eleccion_id=? ORDER BY c.activo DESC,c.seccion,c.nombre');$stmt->bind_param('i',$eid);$stmt->execute();$candidatos=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
